        }
    }
}

DisposableEffect(sharedPrefs, updateListener) {
    sharedPrefs.registerOnSharedPreferenceChangeListener(updateListener)
    onDispose {
        sharedPrefs.unregisterOnSharedPreferenceChangeListener(updateListener)
    }
}
