492:     private fun updateCanSkipPreviousAndNext() {
493:         if (!player.currentTimeline.isEmpty) {
494:             val window =
495:                 player.currentTimeline.getWindow(player.currentMediaItemIndex, Timeline.Window())
496:             canSkipPrevious.value = player.isCommandAvailable(COMMAND_SEEK_IN_CURRENT_MEDIA_ITEM) ||
497:                     !window.isLive ||
498:                     player.isCommandAvailable(COMMAND_SEEK_TO_PREVIOUS_MEDIA_ITEM)
499:             canSkipNext.value = window.isLive &&
500:                     window.isDynamic ||
501:                     player.isCommandAvailable(COMMAND_SEEK_TO_NEXT_MEDIA_ITEM)
502:         } else {
503:             canSkipPrevious.value = false
504:             canSkipNext.value = false
505:         }
506:     }
