40: @OptIn(ExperimentalCoroutinesApi::class)
41: class PlayerConnection(
42:     context: Context,
43:     binder: MusicBinder,
44:     val database: MusicDatabase,
45:     scope: CoroutineScope,
46: ) : Player.Listener {
47:     private companion object {
48:         private const val TAG = "PlayerConnection"
49:         private const val PLAYER_INIT_TIMEOUT_MS = 5000L // 5 second timeout for player initialization
50:     }
51: 
52:     val service = binder.service
53:     private val playerReadinessFlow = service.isPlayerReady
54:     
55:     /**
56:      * Safe player accessor checks readiness & handles errors.
57:      * Should be used by all player access within this class.
58:      */
59:     private fun getPlayerSafe(): ExoPlayer {
60:         return try {
61:             if (!playerReadinessFlow.value) {
62:                 Timber.tag(TAG).w("Player accessed before service initialization complete; returning best-effort reference")
63:             }
64:             service.player
65:         } catch (e: UninitializedPropertyAccessException) {
66:             Timber.tag(TAG).e(e, "Fatal: player property accessed but not initialized")
67:             throw IllegalStateException("MusicService.player not initialized; possible race condition in service startup", e)
68:         }
69:     }
70: 
71:     /**
72:      * Public accessor for player. Throws if player not ready.
73:      * Callers should check [isPlayerInitialized] before calling, or handle exceptions.
74:      */
75:     val player: ExoPlayer
76:         get() = getPlayerSafe()
77: 
78:     /** Tracks whether player initialization completed successfully */
79:     private val isPlayerInitialized = MutableStateFlow(service.isPlayerReady.value)
80: 
81:     val playbackState: MutableStateFlow<Int>
82:     private val playWhenReady: MutableStateFlow<Boolean>
83:     val isPlaying: kotlinx.coroutines.flow.StateFlow<Boolean>
84:     
85:     init {
86:         Timber.tag(TAG).d("PlayerConnection init: playerReady=${playerReadinessFlow.value}")
87:         
88:         // Initialize with player state or safe defaults if player not ready
89:         val initialState = try {
90:             val initialPlayer = getPlayerSafe()
91:             Triple(initialPlayer.playbackState, initialPlayer.playWhenReady, 
92:                    initialPlayer.playWhenReady && initialPlayer.playbackState != STATE_ENDED)
93:         } catch (e: Exception) {
94:             Timber.tag(TAG).e(e, "Error during PlayerConnection initialization, using defaults")
95:             Triple(Player.STATE_IDLE, false, false)
96:         }
97:         
98:         playbackState = MutableStateFlow(initialState.first)
99:         playWhenReady = MutableStateFlow(initialState.second)
100:         isPlaying = combine(playbackState, playWhenReady) { state, ready ->
101:             ready && state != STATE_ENDED
102:         }.stateIn(
103:             scope,
104:             SharingStarted.Lazily,
105:             initialState.third
106:         )
107:         
108:         // Track service readiness changes in background.
109:         scope.launch {
110:             playerReadinessFlow.collect { ready ->
111:                 isPlayerInitialized.value = ready
112:                 if (ready) {
113:                     Timber.tag(TAG).d("Service player initialization detected by PlayerConnection")
114:                 }
115:             }
116:         }
117:         
118:         Timber.tag(TAG).d("PlayerConnection state flows initialized successfully")
119:     }
120:     
121:     // Effective playing state, considers Cast when active
122:     val isEffectivelyPlaying = combine(
123:         isPlaying,
124:         service.castConnectionHandler?.isCasting ?: MutableStateFlow(false),
125:         service.castConnectionHandler?.castIsPlaying ?: MutableStateFlow(false)
126:     ) { localPlaying, isCasting, castPlaying ->
127:         if (isCasting) castPlaying else localPlaying
128:     }.stateIn(
129:         scope,
130:         SharingStarted.Lazily,
131:         player.playbackState != STATE_ENDED && player.playWhenReady
132:     )
133:     
134:     val mediaMetadata = MutableStateFlow(player.currentMetadata)
135:     val currentSong =
136:         mediaMetadata.flatMapLatest {
137:             database.song(it?.id)
138:         }
139:     val currentLyrics = mediaMetadata.flatMapLatest { mediaMetadata ->
140:         database.lyrics(mediaMetadata?.id)
141:     }
142:     val currentFormat =
143:         mediaMetadata.flatMapLatest { mediaMetadata ->
144:             database.format(mediaMetadata?.id)
145:         }
