147:     val radioChips = service.radioChips
148:     val queueTitle = MutableStateFlow<String?>(null)
149:     val queueWindows = MutableStateFlow<List<Timeline.Window>>(emptyList())
150:     val currentMediaItemIndex = MutableStateFlow(-1)
151:     val currentWindowIndex = MutableStateFlow(-1)
152: 
153:     val shuffleModeEnabled = MutableStateFlow(false)
154:     val repeatMode = MutableStateFlow(REPEAT_MODE_OFF)
155: 
156:     val canSkipPrevious = MutableStateFlow(true)
157:     val canSkipNext = MutableStateFlow(true)
158: 
159:     val error = MutableStateFlow<PlaybackException?>(null)
160:     val isMuted = service.isMuted
161: 
162:     val waitingForNetworkConnection = service.waitingForNetworkConnection
