174:     private var attachedPlayer: Player? = null
175: 
176:     init {
177:         try {
178:             // Observe player changes (e.g. crossfade swap)
179:             scope.launch {
180:                 service.playerFlow.collect { newPlayer ->
181:                     if (newPlayer != null && newPlayer != attachedPlayer) {
182:                         updateAttachedPlayer(newPlayer)
183:                     }
184:                 }
185:             }
186:             
187:             // Initial setup if flow hasn't emitted yet but service is ready
188:             if (attachedPlayer == null && service.isPlayerReady.value) {
189:                  updateAttachedPlayer(player)
190:             }
191: 
192:             Timber.tag(TAG).d("PlayerConnection flow observer registered")
193:         } catch (e: Exception) {
194:             Timber.tag(TAG).e(e, "Failed to initialize PlayerConnection listener or state")
195:             // Propagate the error so MainActivity can retry
196:             throw e
197:         }
198:     }
