200:     private fun updateAttachedPlayer(newPlayer: Player) {
201:         attachedPlayer?.removeListener(this)
202:         attachedPlayer = newPlayer
203:         newPlayer.addListener(this)
204:         
205:         // Refresh all state from new player
206:         playbackState.value = newPlayer.playbackState
207:         playWhenReady.value = newPlayer.playWhenReady
208:         mediaMetadata.value = newPlayer.currentMetadata
209:         queueTitle.value = service.queueTitle
210:         queueWindows.value = newPlayer.getQueueWindows()
211:         currentWindowIndex.value = newPlayer.getCurrentQueueIndex()
212:         currentMediaItemIndex.value = newPlayer.currentMediaItemIndex
213:         shuffleModeEnabled.value = newPlayer.shuffleModeEnabled
214:         repeatMode.value = newPlayer.repeatMode
215:         
216:         Timber.tag(TAG).d("Attached to new player instance: $newPlayer")
217:     }
