293:     /**
294:      * Toggle play/pause - handles Cast when active
295:      */
296:     fun togglePlayPause() {
297:         try {
298:             val castHandler = service.castConnectionHandler
299:             if (castHandler?.isCasting?.value == true) {
300:                 if (castHandler.castIsPlaying.value) {
301:                     castHandler.pause()
302:                 } else {
303:                     castHandler.play()
304:                 }
305:             } else {
306:                 player.togglePlayPause()
307:             }
