314:      * Start playback - handles Cast when active
315:      */
316:     fun play() {
317:         try {
318:             val castHandler = service.castConnectionHandler
319:             if (castHandler?.isCasting?.value == true) {
320:                 castHandler.play()
321:             } else {
322:                 if (player.playbackState == Player.STATE_IDLE) {
323:                     player.prepare()
324:                 }
325:                 player.playWhenReady = true
326:             }
327:         } catch (e: Exception) {
