352:         try {
353:             val castHandler = service.castConnectionHandler
354:             if (castHandler?.isCasting?.value == true) {
355:                 castHandler.seekTo(position)
356:             } else {
357:                 player.seekTo(position)
358:             }
359:         } catch (e: Exception) {
