361:         }
362:     }
363: 
364:     fun seekToNext() {
365:         try {
366:             // When casting, use Cast skip instead of local player
367:             val castHandler = service.castConnectionHandler
368:             if (castHandler?.isCasting?.value == true) {
369:                 castHandler.skipToNext()
370:                 return
371:             }
372:             // Try a crossfaded manual skip first (only engages if the user
373:             // enabled "Crossfade on manual skip"); fall back to an instant
374:             // seek otherwise.
375:             if (!service.manualSkipToNextWithCrossfade()) {
376:                 service.cancelCrossfadeIfActive()
377:                 player.seekToNext()
378:                 if (player.playbackState == Player.STATE_IDLE || player.playbackState == Player.STATE_ENDED) {
379:                     player.prepare()
380:                 }
381:                 player.playWhenReady = true
382:             }
383:             onSkipNext?.invoke()
384:         } catch (e: Exception) {
385:             Timber.tag(TAG).e(e, "Error in seekToNext")
386:         }
387:     }
388: 
389:     var onRestartSong: (() -> Unit)? = null
390: 
391:     fun seekToPrevious() {
392:         try {
393:             // When casting, use Cast skip instead of local player
394:             val castHandler = service.castConnectionHandler
395:             if (castHandler?.isCasting?.value == true) {
396:                 castHandler.skipToPrevious()
397:                 return
398:             }
399: 
400:             // Logic to mimic standard seekToPrevious behavior but with explicit callbacks
401:             // If we are more than 3 seconds in, just restart the song
402:             if (player.currentPosition > 3000 || !player.hasPreviousMediaItem()) {
403:                 player.seekTo(0)
404:                 if (player.playbackState == Player.STATE_IDLE || player.playbackState == Player.STATE_ENDED) {
405:                     player.prepare()
406:                 }
407:                 player.playWhenReady = true
408:                 onRestartSong?.invoke()
409:             } else {
410:                 // Otherwise go to previous media item — try a crossfaded
411:                 // manual skip first, falling back to an instant seek.
412:                 if (!service.manualSkipToPreviousWithCrossfade()) {
413:                     service.cancelCrossfadeIfActive()
414:                     player.seekToPreviousMediaItem()
415:                     if (player.playbackState == Player.STATE_IDLE || player.playbackState == Player.STATE_ENDED) {
416:                         player.prepare()
417:                     }
418:                     player.playWhenReady = true
419:                 }
420:                 onSkipPrevious?.invoke()
421:             }
422:         } catch (e: Exception) {
423:             Timber.tag(TAG).e(e, "Error in seekToPrevious")
424:         }
425:     }
426: 
427:     fun seekToQueueItem(index: Int) {
