476:         currentWindowIndex.value = player.getCurrentQueueIndex()
477:         updateCanSkipPreviousAndNext()
478:     }
479: 
480:     override fun onRepeatModeChanged(mode: Int) {
481:         repeatMode.value = mode
482:         updateCanSkipPreviousAndNext()
483:     }
484: 
485:     override fun onPlayerErrorChanged(playbackError: PlaybackException?) {
486:         if (playbackError != null) {
487:             reportException(playbackError)
488:         }
489:         error.value = playbackError
490:     }
491: 
492:     private fun updateCanSkipPreviousAndNext() {
493:         if (!player.currentTimeline.isEmpty) {
494:             val window =
495:                 player.currentTimeline.getWindow(player.currentMediaItemIndex, Timeline.Window())
496:             canSkipPrevious.value = player.isCommandAvailable(COMMAND_SEEK_IN_CURRENT_MEDIA_ITEM) ||
497:                     !window.isLive ||
498:                     player.isCommandAvailable(COMMAND_SEEK_TO_PREVIOUS_MEDIA_ITEM)
499:             canSkipNext.value = window.isLive &&
500:                     window.isDynamic ||
501:                     player.isCommandAvailable(COMMAND_SEEK_TO_NEXT_MEDIA_ITEM)
502:         } else {
503:             canSkipPrevious.value = false
504:             canSkipNext.value = false
505:         }
506:     }
507: 
508:     fun dispose() {
509:         try {
510:             attachedPlayer?.removeListener(this)
511:             attachedPlayer = null
512:             Timber.tag(TAG).d("PlayerConnection disposed successfully")
513:         } catch (e: Exception) {
514:             Timber.tag(TAG).e(e, "Error during PlayerConnection disposal")
515:         }
516:     }
517: }

